	err = json.Unmarshal(file, &discounts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing discounts.json: %v\n", err)
		return Discounts{}
	}

	return discounts
}

func main() {
	items := []Item{
		{Name: "Item1", Price: decimal.NewFromFloat(19.99)},
		{Name: "Item2", Price: decimal.NewFromFloat(19.99)},
		{Name: "Item3", Price: decimal.NewFromFloat(19.99)},
