    let keys: Vec<&str> = key_path.split('.').collect();
    let mut current_value = value;

    for key in keys {
        match current_value {
            toml::Value::Table(table) => {
                current_value = table.get(key)?;
            }
            _ => return None,
        }
    }

    Some(current_value)
}

#[cfg(test)]
mod tests {
    use super::*;
    use toml::Value;

    #[test]
    fn test_get_integer_value() {
        let toml_str = r#"
            server = { port = 8080 }
        "#;
        let value = toml::from_str::<Value>(toml_str).unwrap();
        assert_eq!(get_value(&value, "server.port").unwrap().as_integer(), Some(&8080));
    }

    #[test]
    fn test_get_string_value() {
        let toml_str = r#"
            server = { host = "localhost" }
        "#;
        let value = toml::from_str::<Value>(toml_str).unwrap();
        assert_eq!(get_value(&value, "server.host").unwrap().as_str(), Some(&"localhost"));
    }

    #[test]
    fn test_missing_key() {
        let toml_str = r#"
            server = { port = 8080 }
        "#;
        let value = toml::from_str::<Value>(toml_str).unwrap();
        assert!(get_value(&value, "server.host").is_none());
    }
}
```

### Step 5: Create a README file

We'll create a `README.md` file to explain how to build, use, and test the tool.

